import { clamp, createRng } from "./math";

export { createRng };

export const SIM_WIDTH = 780;
export const SIM_HEIGHT = 440;
export const MID_Y = SIM_HEIGHT / 2;

export const PHOSPHOLIPID_COUNT = 102;
export const WATER_COUNT = 313;

export const HEAD_RADIUS = 6.0;
export const TAIL_LEN = 27;
export const BILAYER_HALF_THICKNESS = 31;
export const WATER_RADIUS = 3.8;
export const FIXED_DT = 1 / 60;

export type BilayerPreset = "random" | "formed";
export type BilayerStatus = "disrupted" | "forming" | "formed";
export type SimulationSpeed = 1 | 2;

export interface Phospholipid {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  /** Direction (radians) from head center toward the hydrophobic tails. */
  angle: number;
  omega: number;
  /** -1 = upper leaflet (tails point down, +pi/2), +1 = lower leaflet (tails point up, -pi/2). */
  leaflet: -1 | 1;
  /** Smoothed hydrophobic shielding factor in [0, 1]. */
  shielded: number;
  /** Tail midpoint X, updated during physics steps and shielding calculation. */
  tmx: number;
  /** Tail midpoint Y, updated during physics steps and shielding calculation. */
  tmy: number;
  /** Organic tail splay / kink asymmetry seed in [-1, 1]. */
  kinkSign: -1 | 1;
}

export interface WaterMolecule {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
}

export interface BlastEvent {
  x: number;
  y: number;
  age: number;
  toastRemaining: number;
}

export interface BilayerTelemetry {
  waterCount: number;
  phospholipidCount: number;
  shieldedPercent: number;
  status: BilayerStatus;
  toastVisible: boolean;
  elapsedSeconds: number;
}

export interface BilayerSimulation {
  phospholipids: Phospholipid[];
  waters: WaterMolecule[];
  preset: BilayerPreset;
  status: BilayerStatus;
  shieldedPercent: number;
  disruptionCooldown: number;
  lastBlast: BlastEvent | null;
  elapsedSeconds: number;
  accumulator: number;
  rng: () => number;
  // Reusable scratch buffers to keep steps allocation-free.
  upperDensity: Float32Array;
  lowerDensity: Float32Array;
  tailNeighbors: Int16Array;
  waterNearTail: Int16Array;
  gridHead: Int32Array;
  gridNext: Int32Array;
}

const CELL_SIZE = 40;
const GRID_COLS = Math.ceil(SIM_WIDTH / CELL_SIZE);
const GRID_ROWS = Math.ceil(SIM_HEIGHT / CELL_SIZE);
const GRID_CELLS = GRID_COLS * GRID_ROWS;

const DENSITY_BINS = 32;
const TAIL_MID_OFFSET = TAIL_LEN * 0.54;
const TOAST_DURATION_SECONDS = 2.8;
const MAX_FRAME_DELTA = 0.05;

const HEAD_MARGIN = HEAD_RADIUS + 4;
const WATER_MARGIN = WATER_RADIUS + 3;

function bounceClamp(value: number, min: number, max: number): number {
  const span = max - min;
  if (span <= 0) return min;
  let v = value - min;
  const period = span * 2;
  v = ((v % period) + period) % period;
  if (v > span) v = period - v;
  return min + v;
}

function normalizeAngle(angle: number): number {
  let a = angle;
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
}

function syncTailMidpoint(lipid: Phospholipid): void {
  lipid.tmx = lipid.x + Math.cos(lipid.angle) * TAIL_MID_OFFSET;
  lipid.tmy = lipid.y + Math.sin(lipid.angle) * TAIL_MID_OFFSET;
}

function populateSimulation(sim: BilayerSimulation, preset: BilayerPreset): void {
  const { phospholipids, waters, rng } = sim;
  phospholipids.length = 0;
  waters.length = 0;

  if (preset === "formed") {
    const perLeaflet = PHOSPHOLIPID_COUNT / 2;
    const xStart = 20;
    const xEnd = SIM_WIDTH - 20;
    const stepX = (xEnd - xStart) / Math.max(1, perLeaflet - 1);

    for (let i = 0; i < perLeaflet; i += 1) {
      const upper: Phospholipid = {
        id: i,
        x: clamp(xStart + i * stepX + (rng() - 0.5) * 3, HEAD_MARGIN, SIM_WIDTH - HEAD_MARGIN),
        y: MID_Y - BILAYER_HALF_THICKNESS + (rng() - 0.5) * 3.5,
        vx: (rng() - 0.5) * 18,
        vy: (rng() - 0.5) * 18,
        angle: Math.PI / 2 + (rng() - 0.5) * 0.14,
        omega: (rng() - 0.5) * 0.3,
        leaflet: -1,
        shielded: 0.96,
        tmx: 0,
        tmy: 0,
        kinkSign: i % 2 === 0 ? 1 : -1,
      };
      syncTailMidpoint(upper);
      phospholipids.push(upper);

      const lower: Phospholipid = {
        id: perLeaflet + i,
        x: clamp(xStart + i * stepX + (rng() - 0.5) * 3, HEAD_MARGIN, SIM_WIDTH - HEAD_MARGIN),
        y: MID_Y + BILAYER_HALF_THICKNESS + (rng() - 0.5) * 3.5,
        vx: (rng() - 0.5) * 18,
        vy: (rng() - 0.5) * 18,
        angle: -Math.PI / 2 + (rng() - 0.5) * 0.14,
        omega: (rng() - 0.5) * 0.3,
        leaflet: 1,
        shielded: 0.96,
        tmx: 0,
        tmy: 0,
        kinkSign: i % 2 === 0 ? -1 : 1,
      };
      syncTailMidpoint(lower);
      phospholipids.push(lower);
    }

    // Place all 313 water molecules exclusively in the upper and lower aqueous compartments.
    const bandClearance = BILAYER_HALF_THICKNESS + HEAD_RADIUS + WATER_RADIUS + 3;
    for (let i = 0; i < WATER_COUNT; i += 1) {
      const isUpper = i % 2 === 0;
      const minY = isUpper ? WATER_MARGIN : MID_Y + bandClearance;
      const maxY = isUpper ? MID_Y - bandClearance : SIM_HEIGHT - WATER_MARGIN;
      waters.push({
        id: i,
        x: WATER_MARGIN + rng() * (SIM_WIDTH - WATER_MARGIN * 2),
        y: minY + rng() * (maxY - minY),
        vx: (rng() - 0.5) * 45,
        vy: (rng() - 0.5) * 45,
      });
    }
  } else {
    // Stratified jittered placement for random solution so starting state is well dispersed.
    const cols = 17;
    const rows = 6;
    const cellW = (SIM_WIDTH - HEAD_MARGIN * 4) / cols;
    const cellH = (SIM_HEIGHT - HEAD_MARGIN * 4) / rows;
    for (let i = 0; i < PHOSPHOLIPID_COUNT; i += 1) {
      const c = i % cols;
      const r = Math.floor(i / cols);
      const x = clamp(
        HEAD_MARGIN * 2 + (c + 0.18 + rng() * 0.64) * cellW,
        HEAD_MARGIN + 8,
        SIM_WIDTH - HEAD_MARGIN - 8,
      );
      const y = clamp(
        HEAD_MARGIN * 2 + (r + 0.18 + rng() * 0.64) * cellH,
        HEAD_MARGIN + 8,
        SIM_HEIGHT - HEAD_MARGIN - 8,
      );
      const leaflet: -1 | 1 = y < MID_Y ? -1 : 1;
      const lipid: Phospholipid = {
        id: i,
        x,
        y,
        vx: (rng() - 0.5) * 90,
        vy: (rng() - 0.5) * 90,
        angle: (rng() - 0.5) * Math.PI * 2,
        omega: (rng() - 0.5) * 2.4,
        leaflet,
        shielded: 0.18,
        tmx: 0,
        tmy: 0,
        kinkSign: i % 2 === 0 ? 1 : -1,
      };
      syncTailMidpoint(lipid);
      phospholipids.push(lipid);
    }

    for (let i = 0; i < WATER_COUNT; i += 1) {
      waters.push({
        id: i,
        x: WATER_MARGIN + rng() * (SIM_WIDTH - WATER_MARGIN * 2),
        y: WATER_MARGIN + rng() * (SIM_HEIGHT - WATER_MARGIN * 2),
        vx: (rng() - 0.5) * 95,
        vy: (rng() - 0.5) * 95,
      });
    }
  }

  sim.preset = preset;
  sim.disruptionCooldown = 0;
  sim.lastBlast = null;
  sim.elapsedSeconds = 0;
  sim.accumulator = 0;
  sim.status = preset === "formed" ? "formed" : "disrupted";
  recomputeShielding(sim, true);
}

export function createBilayerSimulation(options?: {
  preset?: BilayerPreset;
  seed?: number;
}): BilayerSimulation {
  const seed = options?.seed ?? 20261123;
  const preset = options?.preset ?? "random";
  const sim: BilayerSimulation = {
    phospholipids: [],
    waters: [],
    preset,
    status: preset === "formed" ? "formed" : "disrupted",
    shieldedPercent: preset === "formed" ? 96 : 18,
    disruptionCooldown: 0,
    lastBlast: null,
    elapsedSeconds: 0,
    accumulator: 0,
    rng: createRng(seed),
    upperDensity: new Float32Array(DENSITY_BINS),
    lowerDensity: new Float32Array(DENSITY_BINS),
    tailNeighbors: new Int16Array(PHOSPHOLIPID_COUNT),
    waterNearTail: new Int16Array(PHOSPHOLIPID_COUNT),
    gridHead: new Int32Array(GRID_CELLS),
    gridNext: new Int32Array(PHOSPHOLIPID_COUNT + WATER_COUNT),
  };

  populateSimulation(sim, preset);
  return sim;
}

export function resetBilayerSimulation(
  sim: BilayerSimulation,
  preset: BilayerPreset,
  seed?: number,
): void {
  if (seed !== undefined) {
    sim.rng = createRng(seed);
  }
  populateSimulation(sim, preset);
}

export function disruptBilayer(sim: BilayerSimulation, normalizedX = 0.5, normalizedY = 0.5): void {
  const bx = clamp(normalizedX, 0.05, 0.95) * SIM_WIDTH;
  const by = clamp(normalizedY, 0.05, 0.95) * SIM_HEIGHT;
  const { phospholipids, waters, rng } = sim;

  for (let i = 0; i < phospholipids.length; i += 1) {
    const lipid = phospholipids[i]!;
    const dx = lipid.x - bx;
    const dy = lipid.y - by;
    const dist = Math.hypot(dx, dy) + 18;
    const nx = dx / dist;
    const ny = dy / dist;
    const falloff = 1 / (1 + dist / 260);
    const impulse = 320 + falloff * 520 + rng() * 240;
    const verticalScatter = (rng() - 0.5) * 620;
    const horizontalScatter = (rng() - 0.5) * 460;

    lipid.vx += nx * impulse + horizontalScatter;
    lipid.vy += ny * impulse + verticalScatter;
    lipid.omega += (rng() - 0.5) * 14;
    lipid.angle = normalizeAngle(lipid.angle + (rng() - 0.5) * Math.PI * 2);

    // Immediate shockwave scatter across the chamber so lipids disperse visibly even when paused.
    lipid.x = bounceClamp(
      lipid.x + nx * (46 + falloff * 85) + (rng() - 0.5) * 360,
      HEAD_MARGIN,
      SIM_WIDTH - HEAD_MARGIN,
    );
    lipid.y = bounceClamp(
      lipid.y + ny * (60 + falloff * 120) + (rng() - 0.5) * 390,
      HEAD_MARGIN,
      SIM_HEIGHT - HEAD_MARGIN,
    );
    syncTailMidpoint(lipid);
  }

  for (let i = 0; i < waters.length; i += 1) {
    const water = waters[i]!;
    const dx = water.x - bx;
    const dy = water.y - by;
    const dist = Math.hypot(dx, dy) + 14;
    const nx = dx / dist;
    const ny = dy / dist;
    const falloff = 1 / (1 + dist / 260);
    const impulse = 360 + falloff * 540 + rng() * 260;

    water.vx += nx * impulse + (rng() - 0.5) * 520;
    water.vy += ny * impulse + (rng() - 0.5) * 580;
    water.x = bounceClamp(
      water.x + nx * (48 + falloff * 90) + (rng() - 0.5) * 360,
      WATER_MARGIN,
      SIM_WIDTH - WATER_MARGIN,
    );
    water.y = bounceClamp(
      water.y + ny * (62 + falloff * 120) + (rng() - 0.5) * 390,
      WATER_MARGIN,
      SIM_HEIGHT - WATER_MARGIN,
    );
  }

  sim.disruptionCooldown = 1.0;
  sim.lastBlast = {
    x: bx,
    y: by,
    age: 0,
    toastRemaining: TOAST_DURATION_SECONDS,
  };
  sim.status = "disrupted";
  recomputeShielding(sim, true);
}

function buildSpatialHash(sim: BilayerSimulation): void {
  const { gridHead, gridNext, phospholipids, waters } = sim;
  gridHead.fill(-1);

  for (let i = 0; i < phospholipids.length; i += 1) {
    const lipid = phospholipids[i]!;
    syncTailMidpoint(lipid);
    const col = clamp(Math.floor(lipid.tmx / CELL_SIZE), 0, GRID_COLS - 1);
    const row = clamp(Math.floor(lipid.tmy / CELL_SIZE), 0, GRID_ROWS - 1);
    const cell = row * GRID_COLS + col;
    gridNext[i] = gridHead[cell]!;
    gridHead[cell] = i;
  }

  const offset = phospholipids.length;
  for (let i = 0; i < waters.length; i += 1) {
    const water = waters[i]!;
    const col = clamp(Math.floor(water.x / CELL_SIZE), 0, GRID_COLS - 1);
    const row = clamp(Math.floor(water.y / CELL_SIZE), 0, GRID_ROWS - 1);
    const cell = row * GRID_COLS + col;
    const idx = offset + i;
    gridNext[idx] = gridHead[cell]!;
    gridHead[cell] = idx;
  }
}

function recomputeShielding(sim: BilayerSimulation, immediate: boolean): void {
  buildSpatialHash(sim);
  const { phospholipids, waters, gridHead, gridNext, tailNeighbors, waterNearTail } = sim;
  const nLipids = phospholipids.length;

  tailNeighbors.fill(0);
  waterNearTail.fill(0);

  const tailRadiusSq = 38 * 38;
  const waterRadiusSq = 23 * 23;

  for (let i = 0; i < nLipids; i += 1) {
    const a = phospholipids[i]!;
    const col = clamp(Math.floor(a.tmx / CELL_SIZE), 0, GRID_COLS - 1);
    const row = clamp(Math.floor(a.tmy / CELL_SIZE), 0, GRID_ROWS - 1);

    const minC = Math.max(0, col - 1);
    const maxC = Math.min(GRID_COLS - 1, col + 1);
    const minR = Math.max(0, row - 1);
    const maxR = Math.min(GRID_ROWS - 1, row + 1);

    for (let r = minR; r <= maxR; r += 1) {
      for (let c = minC; c <= maxC; c += 1) {
        let idx = gridHead[r * GRID_COLS + c]!;
        while (idx !== -1) {
          if (idx < nLipids) {
            if (idx > i) {
              const b = phospholipids[idx]!;
              const dx = b.tmx - a.tmx;
              const dy = b.tmy - a.tmy;
              if (dx * dx + dy * dy < tailRadiusSq) {
                tailNeighbors[i] = (tailNeighbors[i] ?? 0) + 1;
                tailNeighbors[idx] = (tailNeighbors[idx] ?? 0) + 1;
              }
            }
          } else {
            const w = waters[idx - nLipids]!;
            const dx = w.x - a.tmx;
            const dy = w.y - a.tmy;
            if (dx * dx + dy * dy < waterRadiusSq) {
              waterNearTail[i] = (waterNearTail[i] ?? 0) + 1;
            }
          }
          idx = gridNext[idx]!;
        }
      }
    }
  }

  let total = 0;
  const smoothing = immediate ? 1 : 0.16;
  for (let i = 0; i < nLipids; i += 1) {
    const lipid = phospholipids[i]!;
    const neighbors = tailNeighbors[i] ?? 0;
    const nearbyWater = waterNearTail[i] ?? 0;
    const contactScore =
      neighbors <= 0
        ? 0
        : neighbors === 1
          ? 0.42
          : neighbors === 2
            ? 0.74
            : Math.min(1, neighbors / 3.3);
    const waterFactor = 1 / (1 + 0.65 * nearbyWater);
    const raw = clamp(contactScore * waterFactor, 0, 1);
    lipid.shielded = lipid.shielded + (raw - lipid.shielded) * smoothing;
    total += lipid.shielded;
  }

  const percent = Math.round((total / Math.max(1, nLipids)) * 100);
  sim.shieldedPercent = clamp(percent, 0, 100);

  if (sim.disruptionCooldown > 0.35 || sim.shieldedPercent < 32) {
    sim.status = "disrupted";
  } else if (sim.status === "formed") {
    if (sim.shieldedPercent < 82) {
      sim.status = "forming";
    }
  } else if (sim.shieldedPercent >= 88) {
    sim.status = "formed";
  } else {
    sim.status = "forming";
  }
}

function updateDensityFields(sim: BilayerSimulation): { upperCount: number; lowerCount: number } {
  const { phospholipids, upperDensity, lowerDensity } = sim;
  upperDensity.fill(0);
  lowerDensity.fill(0);

  let upperCount = 0;
  let lowerCount = 0;

  for (let i = 0; i < phospholipids.length; i += 1) {
    const lipid = phospholipids[i]!;
    if (lipid.leaflet === -1) upperCount += 1;
    else lowerCount += 1;

    if (Math.abs(lipid.y - MID_Y) < 76) {
      const binPos = (lipid.x / SIM_WIDTH) * (DENSITY_BINS - 1);
      const b0 = clamp(Math.floor(binPos), 0, DENSITY_BINS - 1);
      const b1 = clamp(b0 + 1, 0, DENSITY_BINS - 1);
      const frac = binPos - b0;
      const target = lipid.leaflet === -1 ? upperDensity : lowerDensity;
      target[b0] = (target[b0] ?? 0) + (1 - frac);
      target[b1] = (target[b1] ?? 0) + frac;
    }
  }

  return { upperCount, lowerCount };
}

function stepSubstep(sim: BilayerSimulation, dt: number): void {
  const { phospholipids, waters, rng, upperDensity, lowerDensity, gridHead, gridNext } = sim;
  const nLipids = phospholipids.length;
  const nWaters = waters.length;

  if (sim.disruptionCooldown > 0) {
    sim.disruptionCooldown = Math.max(0, sim.disruptionCooldown - dt * 1.35);
  }
  if (sim.lastBlast) {
    sim.lastBlast.age += dt;
    sim.lastBlast.toastRemaining = Math.max(0, sim.lastBlast.toastRemaining - dt);
  }

  const assemblyGain = clamp(1 - sim.disruptionCooldown, 0, 1);
  const { upperCount, lowerCount } = updateDensityFields(sim);

  // Locate the least-populated bin in each leaflet to help bulk lipids fill gaps cleanly.
  let minUpperBin = 0;
  let minUpperVal = Infinity;
  let minLowerBin = 0;
  let minLowerVal = Infinity;
  let maxSkewBin = 0;
  let maxSkewDelta = -Infinity;

  for (let b = 1; b < DENSITY_BINS - 1; b += 1) {
    const u = upperDensity[b] ?? 0;
    const l = lowerDensity[b] ?? 0;
    if (u < minUpperVal) {
      minUpperVal = u;
      minUpperBin = b;
    }
    if (l < minLowerVal) {
      minLowerVal = l;
      minLowerBin = b;
    }
    const skew = upperCount > lowerCount ? u - l : l - u;
    if (skew > maxSkewDelta) {
      maxSkewDelta = skew;
      maxSkewBin = b;
    }
  }

  const minUpperX = ((minUpperBin + 0.5) / DENSITY_BINS) * SIM_WIDTH;
  const minLowerX = ((minLowerBin + 0.5) / DENSITY_BINS) * SIM_WIDTH;
  const skewX = ((maxSkewBin + 0.5) / DENSITY_BINS) * SIM_WIDTH;
  const leafletImbalance = upperCount - lowerCount;

  // 1. Brownian jitter + amphiphilic orientation + lateral gap pressure on phospholipids.
  for (let i = 0; i < nLipids; i += 1) {
    const lipid = phospholipids[i]!;

    // Continuous lively Brownian thermal motion.
    lipid.vx += (rng() - 0.5) * 620 * dt;
    lipid.vy += (rng() - 0.5) * 620 * dt;
    lipid.omega += (rng() - 0.5) * 10 * dt;

    // Leaflet assignment based on which side of the bilayer midplane the lipid approaches from.
    if (assemblyGain > 0.15) {
      if (lipid.y < MID_Y - 12 && Math.abs(lipid.y - MID_Y) > 14) {
        lipid.leaflet = -1;
      } else if (lipid.y > MID_Y + 12 && Math.abs(lipid.y - MID_Y) > 14) {
        lipid.leaflet = 1;
      }
    }

    const targetY = MID_Y + lipid.leaflet * BILAYER_HALF_THICKNESS;
    const dyToTarget = targetY - lipid.y;
    const targetAngle = lipid.leaflet === -1 ? Math.PI / 2 : -Math.PI / 2;
    const angleErr = normalizeAngle(targetAngle - lipid.angle);

    // Amphiphilic hydrophobic-effect pull toward the midplane + restoring orientation torque.
    const pullStrength = 3.2 * assemblyGain;
    lipid.vy += clamp(dyToTarget * pullStrength, -420, 420) * dt;
    lipid.omega += angleErr * (11.5 * assemblyGain) * dt;

    // 1D lateral density pressure inside the bilayer keeps spacing uniform and fills gaps.
    const binIdx = clamp(
      Math.round((lipid.x / SIM_WIDTH) * (DENSITY_BINS - 1)),
      0,
      DENSITY_BINS - 1,
    );
    const densityArr = lipid.leaflet === -1 ? upperDensity : lowerDensity;
    const leftD = densityArr[Math.max(0, binIdx - 1)] ?? 0;
    const rightD = densityArr[Math.min(DENSITY_BINS - 1, binIdx + 1)] ?? 0;
    const hereD = densityArr[binIdx] ?? 0;

    if (Math.abs(lipid.y - MID_Y) < 72) {
      const gradX = rightD - leftD;
      lipid.vx -= gradX * (155 * assemblyGain) * dt;
    }

    // Guide bulk lipids toward open horizontal gaps so no lipid remains stranded behind heads.
    if (Math.abs(lipid.y - targetY) > 16 && hereD > 1.35) {
      const gapX = lipid.leaflet === -1 ? minUpperX : minLowerX;
      const dxGap = gapX - lipid.x;
      lipid.vx += clamp(dxGap * 1.4, -220, 220) * assemblyGain * dt;
    }

    // Relieve leaflet count imbalance (> 2 excess lipids) at the most skewed lateral zone.
    if (assemblyGain > 0.35 && Math.abs(leafletImbalance) > 2) {
      const isOvercrowdedSide =
        (leafletImbalance > 2 && lipid.leaflet === -1) ||
        (leafletImbalance < -2 && lipid.leaflet === 1);
      if (isOvercrowdedSide && Math.abs(lipid.x - skewX) < 55) {
        const flipDir = leafletImbalance > 2 ? 1 : -1;
        lipid.vy += flipDir * 290 * assemblyGain * dt;
        if (flipDir > 0 && lipid.y > MID_Y + 4) lipid.leaflet = 1;
        else if (flipDir < 0 && lipid.y < MID_Y - 4) lipid.leaflet = -1;
      }
    }
  }

  // 2. Brownian jitter + continuous hydrophobic bilayer core exclusion on water molecules.
  for (let i = 0; i < nWaters; i += 1) {
    const water = waters[i]!;
    water.vx += (rng() - 0.5) * 760 * dt;
    water.vy += (rng() - 0.5) * 760 * dt;

    if (assemblyGain > 0.45) {
      const distMid = water.y - MID_Y;
      if (Math.abs(distMid) < 30) {
        const binIdx = clamp(
          Math.round((water.x / SIM_WIDTH) * (DENSITY_BINS - 1)),
          0,
          DENSITY_BINS - 1,
        );
        const coreDensity = (upperDensity[binIdx] ?? 0) + (lowerDensity[binIdx] ?? 0);
        if (coreDensity > 0.45) {
          const sign = distMid === 0 ? (i % 2 === 0 ? -1 : 1) : Math.sign(distMid);
          const strength = clamp((coreDensity - 0.45) / 2.2, 0.25, 1) * assemblyGain;
          water.vy += sign * (1 - Math.abs(distMid) / 32) * 1400 * strength * dt;
        }
      }
    }
  }

  // 3. Pairwise interactions via spatial hash.
  buildSpatialHash(sim);

  const headRepelDist = 13.8;
  const headRepelSq = headRepelDist * headRepelDist;
  const tailRepelDist = 10.5;
  const tailAttractDist = 42;
  const tailAttractSq = tailAttractDist * tailAttractDist;

  const waterTailRepel = 21.5;
  const waterTailRepelSq = waterTailRepel * waterTailRepel;
  const waterHeadRepel = 11.2;
  const waterHeadHydrate = 19;
  const waterHeadHydrateSq = waterHeadHydrate * waterHeadHydrate;
  const waterWaterDist = 14;
  const waterWaterSq = waterWaterDist * waterWaterDist;

  for (let i = 0; i < nLipids; i += 1) {
    const a = phospholipids[i]!;
    const col = clamp(Math.floor(a.tmx / CELL_SIZE), 0, GRID_COLS - 1);
    const row = clamp(Math.floor(a.tmy / CELL_SIZE), 0, GRID_ROWS - 1);
    const minC = Math.max(0, col - 1);
    const maxC = Math.min(GRID_COLS - 1, col + 1);
    const minR = Math.max(0, row - 1);
    const maxR = Math.min(GRID_ROWS - 1, row + 1);

    for (let r = minR; r <= maxR; r += 1) {
      for (let c = minC; c <= maxC; c += 1) {
        let idx = gridHead[r * GRID_COLS + c]!;
        while (idx !== -1) {
          if (idx < nLipids) {
            if (idx > i) {
              const b = phospholipids[idx]!;
              // Head-head steric repulsion.
              const hdx = b.x - a.x;
              const hdy = b.y - a.y;
              const hdSq = hdx * hdx + hdy * hdy;
              if (hdSq > 0.0001 && hdSq < headRepelSq) {
                const hd = Math.sqrt(hdSq);
                const push = ((headRepelDist - hd) / headRepelDist) * 1650 * dt;
                const nx = hdx / hd;
                const ny = hdy / hd;
                a.vx -= nx * push;
                a.vy -= ny * push;
                b.vx += nx * push;
                b.vy += ny * push;
              }

              // Tail-tail short-range steric core + hydrophobic attraction + local alignment.
              const tdx = b.tmx - a.tmx;
              const tdy = b.tmy - a.tmy;
              const tdSq = tdx * tdx + tdy * tdy;
              if (tdSq > 0.0001 && tdSq < tailAttractSq) {
                const td = Math.sqrt(tdSq);
                const nx = tdx / td;
                const ny = tdy / td;
                if (td < tailRepelDist) {
                  const push = ((tailRepelDist - td) / tailRepelDist) * 900 * dt;
                  a.vx -= nx * push;
                  a.vy -= ny * push;
                  b.vx += nx * push;
                  b.vy += ny * push;
                } else {
                  const pull =
                    (1 - (td - tailRepelDist) / (tailAttractDist - tailRepelDist)) *
                    260 *
                    assemblyGain *
                    dt;
                  a.vx += nx * pull;
                  a.vy += ny * pull;
                  b.vx -= nx * pull;
                  b.vy -= ny * pull;

                  // Parallel or anti-parallel tail alignment in free clusters.
                  const alignDiff = normalizeAngle(b.angle - a.angle);
                  const antiDiff = normalizeAngle(b.angle + Math.PI - a.angle);
                  const chosenDiff =
                    Math.abs(alignDiff) < Math.abs(antiDiff) ? alignDiff : antiDiff;
                  const torque = chosenDiff * 2.2 * assemblyGain * dt;
                  a.omega += torque;
                  b.omega -= torque;
                }
              }
            }
          } else {
            const w = waters[idx - nLipids]!;
            // Water-tail hydrophobic repulsion.
            const wtdx = w.x - a.tmx;
            const wtdy = w.y - a.tmy;
            const wtdSq = wtdx * wtdx + wtdy * wtdy;
            if (wtdSq > 0.0001 && wtdSq < waterTailRepelSq) {
              const wtd = Math.sqrt(wtdSq);
              const push = ((waterTailRepel - wtd) / waterTailRepel) * 1450 * dt;
              const nx = wtdx / wtd;
              const ny = wtdy / wtd;
              w.vx += nx * push;
              w.vy += ny * push;
              a.vx -= nx * push * 0.14;
              a.vy -= ny * push * 0.14;
            }

            // Water-head steric repulsion + subtle outer hydration attraction.
            const whdx = w.x - a.x;
            const whdy = w.y - a.y;
            const whdSq = whdx * whdx + whdy * whdy;
            if (whdSq > 0.0001 && whdSq < waterHeadHydrateSq) {
              const whd = Math.sqrt(whdSq);
              const nx = whdx / whd;
              const ny = whdy / whd;
              if (whd < waterHeadRepel) {
                const push = ((waterHeadRepel - whd) / waterHeadRepel) * 1250 * dt;
                w.vx += nx * push;
                w.vy += ny * push;
              } else {
                const hydrate = 85 * assemblyGain * dt;
                w.vx -= nx * hydrate;
                w.vy -= ny * hydrate;
              }
            }
          }
          idx = gridNext[idx]!;
        }
      }
    }
  }

  // Water-water soft dispersion so water does not clump.
  for (let i = 0; i < nWaters; i += 1) {
    const a = waters[i]!;
    const col = clamp(Math.floor(a.x / CELL_SIZE), 0, GRID_COLS - 1);
    const row = clamp(Math.floor(a.y / CELL_SIZE), 0, GRID_ROWS - 1);
    const minC = Math.max(0, col - 1);
    const maxC = Math.min(GRID_COLS - 1, col + 1);
    const minR = Math.max(0, row - 1);
    const maxR = Math.min(GRID_ROWS - 1, row + 1);

    for (let r = minR; r <= maxR; r += 1) {
      for (let c = minC; c <= maxC; c += 1) {
        let idx = gridHead[r * GRID_COLS + c]!;
        while (idx !== -1) {
          if (idx >= nLipids) {
            const wi = idx - nLipids;
            if (wi > i) {
              const b = waters[wi]!;
              const dx = b.x - a.x;
              const dy = b.y - a.y;
              const dSq = dx * dx + dy * dy;
              if (dSq > 0.0001 && dSq < waterWaterSq) {
                const d = Math.sqrt(dSq);
                const push = ((waterWaterDist - d) / waterWaterDist) * 760 * dt;
                const nx = dx / d;
                const ny = dy / d;
                a.vx -= nx * push;
                a.vy -= ny * push;
                b.vx += nx * push;
                b.vy += ny * push;
              }
            }
          }
          idx = gridNext[idx]!;
        }
      }
    }
  }

  // 4. Viscous damping, integration, and reflective container walls.
  const linearDamp = Math.pow(0.91, dt * 60);
  const angularDamp = Math.pow(0.84, dt * 60);
  const maxLipidSpeed = 520;
  const maxWaterSpeed = 560;

  for (let i = 0; i < nLipids; i += 1) {
    const lipid = phospholipids[i]!;
    lipid.vx = clamp(lipid.vx * linearDamp, -maxLipidSpeed, maxLipidSpeed);
    lipid.vy = clamp(lipid.vy * linearDamp, -maxLipidSpeed, maxLipidSpeed);
    lipid.omega = clamp(lipid.omega * angularDamp, -12, 12);

    lipid.x += lipid.vx * dt;
    lipid.y += lipid.vy * dt;
    lipid.angle = normalizeAngle(lipid.angle + lipid.omega * dt);

    if (lipid.x < HEAD_MARGIN) {
      lipid.x = HEAD_MARGIN;
      lipid.vx = Math.abs(lipid.vx) * 0.7;
    } else if (lipid.x > SIM_WIDTH - HEAD_MARGIN) {
      lipid.x = SIM_WIDTH - HEAD_MARGIN;
      lipid.vx = -Math.abs(lipid.vx) * 0.7;
    }

    if (lipid.y < HEAD_MARGIN) {
      lipid.y = HEAD_MARGIN;
      lipid.vy = Math.abs(lipid.vy) * 0.7;
    } else if (lipid.y > SIM_HEIGHT - HEAD_MARGIN) {
      lipid.y = SIM_HEIGHT - HEAD_MARGIN;
      lipid.vy = -Math.abs(lipid.vy) * 0.7;
    }

    syncTailMidpoint(lipid);
  }

  for (let i = 0; i < nWaters; i += 1) {
    const water = waters[i]!;
    water.vx = clamp(water.vx * linearDamp, -maxWaterSpeed, maxWaterSpeed);
    water.vy = clamp(water.vy * linearDamp, -maxWaterSpeed, maxWaterSpeed);

    water.x += water.vx * dt;
    water.y += water.vy * dt;

    if (water.x < WATER_MARGIN) {
      water.x = WATER_MARGIN;
      water.vx = Math.abs(water.vx) * 0.8;
    } else if (water.x > SIM_WIDTH - WATER_MARGIN) {
      water.x = SIM_WIDTH - WATER_MARGIN;
      water.vx = -Math.abs(water.vx) * 0.8;
    }

    if (water.y < WATER_MARGIN) {
      water.y = WATER_MARGIN;
      water.vy = Math.abs(water.vy) * 0.8;
    } else if (water.y > SIM_HEIGHT - WATER_MARGIN) {
      water.y = SIM_HEIGHT - WATER_MARGIN;
      water.vy = -Math.abs(water.vy) * 0.8;
    }
  }

  sim.elapsedSeconds += dt;
  recomputeShielding(sim, false);
}

export function stepBilayerSimulation(
  sim: BilayerSimulation,
  elapsedSeconds: number,
  speed: SimulationSpeed = 1,
): void {
  const clampedDelta = clamp(elapsedSeconds, 0, MAX_FRAME_DELTA);
  if (clampedDelta <= 0) return;

  sim.accumulator += clampedDelta * speed;
  while (sim.accumulator >= FIXED_DT) {
    stepSubstep(sim, FIXED_DT);
    sim.accumulator -= FIXED_DT;
  }
}

export function getBilayerTelemetry(sim: BilayerSimulation): BilayerTelemetry {
  return {
    waterCount: sim.waters.length,
    phospholipidCount: sim.phospholipids.length,
    shieldedPercent: sim.shieldedPercent,
    status: sim.status,
    toastVisible: Boolean(sim.lastBlast && sim.lastBlast.toastRemaining > 0),
    elapsedSeconds: sim.elapsedSeconds,
  };
}

/** Compare UI-visible bilayer telemetry fields so continuous elapsedSeconds ticks do not force React re-renders. */
export function sameBilayerTelemetry(a: BilayerTelemetry, b: BilayerTelemetry): boolean {
  return (
    a.waterCount === b.waterCount &&
    a.phospholipidCount === b.phospholipidCount &&
    a.shieldedPercent === b.shieldedPercent &&
    a.status === b.status &&
    a.toastVisible === b.toastVisible
  );
}
